'use strict';
// Save slots are independent from optional, per-match analytics.
const SAVE_KEY='sechser.saves.v1', CONSENT_KEY='sechser.analytics.v1';
const initialSquad=structuredClone(players), initialKeeper=structuredClone(homeKeeper);
let activeSave=null, storageFailed=false;
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readSlots(){try{const data=JSON.parse(localStorage.getItem(SAVE_KEY)||'[]');if(!Array.isArray(data))throw Error();return data}catch{storageFailed=true;return []}}
function persistSlots(slots){try{localStorage.setItem(SAVE_KEY,JSON.stringify(slots));storageFailed=false;return true}catch{storageFailed=true;alert('Speichern fehlgeschlagen. Bitte freien Browserspeicher prüfen. Dein geöffnetes Spiel bleibt erhalten.');return false}}
const menu=document.createElement('main');menu.id='start-screen';menu.innerHTML=`<section class="intro"><div><p class="eyebrow">DEIN VEREIN. DEIN FUSSBALL.</p><h1>Willkommen bei SECHSER.</h1><p class="help">Fünf Feldspieler. Ein Torwart. Und dein Plan.</p></div></section><div class="menu-layout"><section class="panel"><h2>Deine nächste Fußballgeschichte</h2><p class="help">Gründe deinen eigenen Verein und bring deine Taktik auf den Platz.</p><button id="new-game" class="primary">Neues Spiel <span>↗</span></button><form id="club-form" hidden><label for="club-name">Vereinsname</label><input id="club-name" maxlength="28" value="FC Viertel" required><button class="primary" type="submit">Verein gründen</button><button type="button" id="cancel-create" class="menu-action">Abbrechen</button></form></section><section class="panel"><h2>Gespeicherte Spiele</h2><p class="help">Automatisch gespeichert auf diesem Gerät und in diesem Browser. Laufende Matches werden nicht gespeichert.</p><div id="save-list"></div></section></div><section class="panel"><h2>Spieldaten teilen</h2><p class="help">Freiwillig: Nach jedem abgeschlossenen Match werden Ergebnis, Taktik und Spielerstatistiken zur Verbesserung der Simulation gesendet. Ohne Vereinsnamen, Spielernamen oder dauerhafte Nutzerkennung. Spielzusammenfassungen, die älter als 90 Tage sind, werden beim nächsten Dateneingang gelöscht. Der Hostinganbieter verarbeitet bei der Verbindung technisch deine IP-Adresse; die Spielauswertung speichert sie nicht.</p><div class="privacy-actions"><button id="share-yes" class="menu-action">Spieldaten teilen</button><button id="share-no" class="menu-action">Nur lokal spielen</button></div><p id="share-status" class="help" role="status"></p><p class="help">Die Auswahl gilt für diesen Browser und lässt sich hier jederzeit ändern. Bereits übertragene Daten können ohne Nutzerkennung keinem Spielstand zugeordnet werden. Beim Löschen eines Spielstands bleiben diese Zusammenfassungen bis zum Ablauf der Speicherfrist erhalten.</p></section><footer>SECHSER / PROTOTYP 10</footer>`;
$('#game-screen').before(menu);
const menuButton=document.createElement('button');menuButton.className='menu-action';menuButton.textContent='Speichern & zum Startscreen';$('#game-screen aside').append(menuButton);
function analyticsEnabled(){try{return localStorage.getItem(CONSENT_KEY)==='yes'}catch{return false}}
function consentStatus(){const enabled=analyticsEnabled();$('#share-status').textContent=enabled?'Teilen aktiviert. Änderung jederzeit möglich.':'Nur lokal: Es werden keine Spielzusammenfassungen gesendet.';$('#share-yes').setAttribute('aria-pressed',enabled);$('#share-no').setAttribute('aria-pressed',!enabled)}
for(const [id,value] of [['#share-yes','yes'],['#share-no','no']])$(id).onclick=()=>{try{localStorage.setItem(CONSENT_KEY,value)}catch{alert('Die Auswahl konnte nicht gespeichert werden. Es werden keine Spieldaten gesendet.')}consentStatus()};
function drawSlots(){const slots=readSlots();$('#save-list').innerHTML=storageFailed?'<p class="help">Die Spielstände konnten nicht gelesen werden. Vorhandene Daten werden nicht überschrieben.</p>':slots.length?slots.map(s=>`<article class="save-slot"><div><strong>${escapeHTML(s.club)}</strong><p class="help">${s.games||0} Spiele · ${escapeHTML(new Date(s.updated).toLocaleString('de-AT'))}</p></div><div class="privacy-actions"><button class="menu-action" data-load="${escapeHTML(s.id)}">Fortsetzen</button><button class="menu-action danger" data-delete="${escapeHTML(s.id)}">Löschen</button></div></article>`).join(''):'<p class="help">Noch kein Spielstand. Dein erster Verein wartet auf dich.</p>'}
function saveCurrent(){if(!activeSave)return true;const slots=readSlots();if(storageFailed){alert('Vorhandene Spielstände konnten nicht gelesen werden. Speichern wurde abgebrochen.');return false}const next={...activeSave,schema:1,updated:new Date().toISOString(),players:structuredClone(players),keeper:structuredClone(homeKeeper),formation,press,direct};const index=slots.findIndex(s=>s.id===next.id);if(index<0)slots.push(next);else slots[index]=next;if(!persistSlots(slots))return false;activeSave=next;return true}
function openSlot(slot){if(slot.schema!==1||!Array.isArray(slot.players)||slot.players.length!==5||!slot.keeper||!slot.players.every(p=>Number.isInteger(p.cell)&&p.cell>=0&&p.cell<35)||new Set(slot.players.map(p=>p.cell)).size!==5){alert('Dieser Spielstand ist beschädigt oder gehört zu einer neueren Version.');return}activeSave=structuredClone(slot);players.splice(0,players.length,...structuredClone(slot.players));{for(const key of Object.keys(homeKeeper))delete homeKeeper[key];Object.assign(homeKeeper,structuredClone(slot.keeper))};formation=formations[slot.formation]?slot.formation:'custom';press=slot.press?1:0;direct=slot.direct?1:0;selected=0;$('#back').onclick();for(const [type,value] of [['press',press],['pass',direct]])$$(`[data-${type}]`).forEach(b=>b.classList.toggle('active',+b.dataset[type]===value));$('.board-top strong').textContent=activeSave.club;$('.scoreboard span').textContent=activeSave.club;menu.hidden=true;$('#game-screen').hidden=false;render();window.scrollTo(0,0)}
$('#new-game').onclick=()=>{$('#club-form').hidden=false;$('#club-name').focus()};$('#cancel-create').onclick=()=>$('#club-form').hidden=true;
$('#club-form').onsubmit=e=>{e.preventDefault();const name=$('#club-name').value.trim();if(!name)return;const slots=readSlots();if(storageFailed)return;const slot={schema:1,id:crypto.randomUUID(),club:name,games:0,updated:new Date().toISOString(),players:structuredClone(initialSquad),keeper:structuredClone(initialKeeper),formation:'balanced',press:0,direct:0};if(persistSlots([...slots,slot])){$('#club-form').hidden=true;openSlot(slot)}};
$('#save-list').onclick=e=>{const load=e.target.closest('[data-load]'),del=e.target.closest('[data-delete]');if(load){const slot=readSlots().find(s=>s.id===load.dataset.load);if(slot)openSlot(slot)}if(del){const slots=readSlots(),slot=slots.find(s=>s.id===del.dataset.delete);if(slot&&confirm(`„${slot.club}“ und alle lokalen Fortschritte endgültig löschen?`)){if(persistSlots(slots.filter(s=>s.id!==slot.id)))drawSlots()}}};
menuButton.onclick=()=>{if(running)return;if(saveCurrent()){$('#game-screen').hidden=true;menu.hidden=false;drawSlots();window.scrollTo(0,0)}};
$('#game-screen').addEventListener('click',e=>{if(!running&&e.target.closest('[data-cell],[data-role],[data-formation],[data-press],[data-pass]'))saveCurrent()});
const originalStart=start;start=function(){if(!activeSave||running)return;saveCurrent();menuButton.disabled=true;originalStart();$('#subtitle').textContent=`${activeSave.club} gegen SC Hafen · 40 Spielminuten`};$('#start').onclick=()=>start();
const originalNote=note;note=function(text,kind){originalNote(text.replaceAll('FC Viertel',activeSave?.club||'FC Viertel'),kind)};
const originalOverlay=showOverlay;showOverlay=function(title,copy,...args){originalOverlay(title,copy.replaceAll('FC Viertel',activeSave?.club||'FC Viertel'),...args)};
const originalFinish=finishMatch;finishMatch=function(){if(match.finished)return;originalFinish();menuButton.disabled=false;if(match.score[0]>match.score[1])$('#match-title').textContent=`Sieg für ${activeSave.club}!`;activeSave.games++;for(const person of match.people.filter(p=>p.t===0)){const source=person.keeper?homeKeeper:players.find(p=>p.n===person.n);source.season=source.season||{games:0};source.season.games++;for(const [key,value] of Object.entries(person.stats))if(key!=='rating')source.season[key]=(source.season[key]||0)+value}saveCurrent();sendMatchSummary()};
async function sendMatchSummary(){if(!analyticsEnabled()||!['http:','https:'].includes(location.protocol))return;const payload={schema:1,version:'0.10',id:crypto.randomUUID(),formation,press,direct,score:match.score,shots:match.shots,players:match.people.map(p=>({team:p.t,line:p.line,age:p.age,form:p.form,fresh:Math.round(p.fresh),stats:p.stats}))};try{const response=await fetch('/api/match.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload),keepalive:true});if(!response.ok)throw Error();$('#share-status').textContent='Letzte Spielzusammenfassung erfolgreich übertragen.'}catch{$('#share-status').textContent='Letzte Übertragung nicht möglich. Dein Spielstand ist weiterhin lokal gespeichert.'}}
$('.brand').onclick=e=>{e.preventDefault();if(!running)menuButton.click()};
drawSlots();consentStatus();
